#include <stdio.h>

int main(void) {
    long long a, b;
    scanf("%lld %lld", &a, &b);
    long long div3  = b/3  - (a-1)/3;
    long long div7  = b/7  - (a-1)/7;
    long long div21 = b/21 - (a-1)/21;
    printf("%lld\n", div3 + div7 - div21);
    return 0;
}

#include <stdio.h>
#include <math.h>

#define PI 3.14159265
#define R 6371.0

int main(void) {
    double lat1, lon1, lat2, lon2;
    scanf("%lf %lf %lf %lf", &lat1, &lon1, &lat2, &lon2);

    lat1 = lat1 * PI / 180.0;
    lon1 = lon1 * PI / 180.0;
    lat2 = lat2 * PI / 180.0;
    lon2 = lon2 * PI / 180.0;

    double dlat = lat2 - lat1;
    double dlon = lon2 - lon1;

    double a = sin(dlat/2.0)*sin(dlat/2.0) + cos(lat1)*cos(lat2)*sin(dlon/2.0)*sin(dlon/2.0);
    double c = 2.0 * asin(sqrt(a));

    printf("%.2f\n", R * c);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);
    int maiorAB = (a + b + abs(a - b)) / 2;
    int maiorABC = (maiorAB + c + abs(maiorAB - c)) / 2;
    printf("%d\n", maiorABC);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double a, b, c;
    scanf("%lf %lf %lf", &a, &b, &c);
    double s = (a + b + c) / 2.0;
    double area = sqrt(s * (s - a) * (s - b) * (s - c));
    printf("%.4f\n", area);
    return 0;
}

#include <stdio.h>

int main(void) {
    double x1, y1, x2, y2;
    scanf("%lf %lf %lf %lf", &x1, &y1, &x2, &y2);
    double largura = x2 > x1 ? x2 - x1 : x1 - x2;
    double altura = y2 > y1 ? y2 - y1 : y1 - y2;
    double perimetro = 2.0 * (largura + altura);
    double area = largura * altura;
    printf("%.2f\n%.2f\n", perimetro, area);
    return 0;
}

#include <stdio.h>
#include <math.h>

#define G 6.67430e-11

int main(void) {
    double m1, m2, d;
    scanf("%lf %lf %lf", &m1, &m2, &d);
    double f = G * (m1 * m2) / (d * d);
    printf("%.4e\n", f);
    return 0;
}

#include <stdio.h>
#include <math.h>

#define PI 3.14159265

int main(void) {
    double graus;
    scanf("%lf", &graus);
    double rad = graus * PI / 180.0;
    double val = sin(rad) * sin(rad) + cos(rad) * cos(rad);
    printf("%.6f\n", val);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double montante, taxa;
    double anos;
    scanf("%lf %lf %lf", &montante, &taxa, &anos);
    double p = montante / pow(1.0 + taxa / 100.0, anos);
    printf("%.2f\n", p);
    return 0;
}
